LW, LD, ST, XP, ZP, NL = 16, 22, 10, 138, 32, 8
PLAZA = (-32.5, 32.5, -64, -18); LAKE = (-640, 140, 150, 110)
def read(p):
    t = pathlib.Path(p).read_text(encoding='utf-8')
    if p.endswith('.json'):
        d = json.loads(t); d = d.get('relationships_followers', d) if isinstance(d, dict) else d; out = []
        for it in d:
            for s in it.get('string_list_data', []):
                if s.get('value'): out.append(s['value'])
            if not it.get('string_list_data') and it.get('title'): out.append(it['title'])
        return out[::-1]
    if p.endswith('.html'): return re.findall(r'instagram\.com/(?:_u/)?([A-Za-z0-9._]+)"', t)[::-1]
    return [w.lstrip('@').strip() for w in re.split(r'[\n,;]+', t) if w.strip()]
db = json.load(open('residents.json')) if os.path.exists('residents.json') else {'residents': []}
R = db['residents']; idx = {r['nickname'].lower(): r for r in R}; seen = set()
for n in read(sys.argv[1]):
    if not re.fullmatch(r'[A-Za-z0-9._]{1,30}', n) or n.lower() in seen: continue
    seen.add(n.lower())
    if n.lower() not in idx: r = {'id': len(R) + 1, 'nickname': n, 'status': 'active'}; R.append(r); idx[n.lower()] = r
for r in R: r['status'] = 'active' if r['nickname'].lower() in seen else 'dark'
json.dump(db, open('residents.json', 'w'), ensure_ascii=False, indent=1)
def free(x0, x1, z0, z1):
    if x1 > PLAZA[0] - 6 and x0 < PLAZA[1] + 6 and z1 > PLAZA[2] - 6 and z0 < PLAZA[3] + 6: return False
    cx, cz = (x0 + x1) / 2, (z0 + z1) / 2
    return ((cx - LAKE[0]) / LAKE[2]) ** 2 + ((cz - LAKE[1]) / LAKE[3]) ** 2 >= 1
