rows = []; num = {}
for r, (x, z, si) in zip(R, order):
    rnd = random.Random(r['id'] * 7919); t = rnd.choice(list(PAL)); p = rnd.choice(PAL[t]); num[si] = num.get(si, 0) + 1
    rows.append([r['id'], r['nickname'], t, x, z + 5, p['w'], p['d'], p['h'], p['wall'], p['trim'], p['roof'], p['accent'], r['status'], si, num[si], [x - LW / 2, z, x + LW / 2, z + LD], 1, {}])
F = [[x, z + 5, si] for (x, z, si) in order[len(R):len(R) + 80]]
js = "const K=" + json.dumps(K) + ";\nconst R=" + json.dumps(rows, ensure_ascii=False, separators=(',', ':')) + ";\nconst F=" + json.dumps(F) + ";\n"
